package thaumcraft.datagen;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.HexFormat;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class ShaderResourcesTest {
    @Test void fifteenResourcesMatchBoundedManifestHashesAndActualBytes()throws Exception{var manifest=TCShaderResourcesProvider.read();for(var entry:manifest.getAsJsonArray("entries")){var row=entry.getAsJsonObject();try(var stream=getClass().getClassLoader().getResourceAsStream(row.get("path").getAsString())){assertNotNull(stream);byte[] bytes=stream.readAllBytes();assertEquals(row.get("payload").getAsString(),new String(bytes,StandardCharsets.UTF_8));assertEquals(row.get("sha256").getAsString(),HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes)));}}}
    @Test void originalFiveFilesDescribeTwoCompiledProgramsAndUnusedTest(){var manifest=TCShaderResourcesProvider.read();assertEquals(5,manifest.get("rawFileCount").getAsInt());assertEquals(2,manifest.get("sourceProgramCount").getAsInt());assertEquals("no source consumer",manifest.get("testFragmentActivation").getAsString());assertEquals("compiled, no source consumer",manifest.get("sketchActivation").getAsString());}
    @Test void originalEnderAlgorithmAndSketchNeighborQuantizationAreNotVanillaSubstitutes(){var manifest=TCShaderResourcesProvider.read();String ender="",sketch="",mirror="";for(var value:manifest.getAsJsonArray("entries")){var row=value.getAsJsonObject();String path=row.get("path").getAsString();if(path.endsWith("boss_ender.fsh"))ender=row.get("payload").getAsString();if(path.endsWith("source_sketch.fsh"))sketch=row.get("payload").getAsString();if(path.endsWith("source_mirror.fsh"))mirror=row.get("payload").getAsString();}assertTrue(ender.contains("i<16"));assertTrue(ender.contains("time * 0.00006"));assertTrue(ender.contains("ShaderEnabled == 0"));assertTrue(sketch.contains("up2"));assertTrue(sketch.contains("LumaLevel / (LumaLevel - 1.0)"));assertTrue(mirror.contains("textureProj"));}
    @Test void duplicateAndTraversalShaderOutputsAreRejected(){var duplicate=TCShaderResourcesProvider.read().deepCopy();duplicate.getAsJsonArray("entries").get(1).getAsJsonObject().addProperty("path",duplicate.getAsJsonArray("entries").get(0).getAsJsonObject().get("path").getAsString());assertThrows(IllegalArgumentException.class,()->TCShaderResourcesProvider.validate(duplicate));var traversal=TCShaderResourcesProvider.read().deepCopy();traversal.getAsJsonArray("entries").get(0).getAsJsonObject().addProperty("path","assets/thaumcraft/shaders/core/../bad.fsh");assertThrows(IllegalArgumentException.class,()->TCShaderResourcesProvider.validate(traversal));}
}
